-- English → Japanese starter pack. The client keeps the historical `en`/`pl`
-- JSON keys for compatibility; `fieldLocales` defines the actual target as ja-JP.

INSERT OR REPLACE INTO language_pairs (
  id, source_language, target_language, source_locale, target_locale, ui_locale,
  source_voice, target_voice, target_slow_voices_json, description, active
) VALUES (
  'en-ja', 'English', 'Japanese', 'en-US', 'ja-JP', 'en-US',
  'en-US-JennyNeural', 'ja-JP-NanamiNeural',
  '["ja-JP-NanamiNeural|slow60v1"]',
  'Japanese study for English speakers, with natural slowed Japanese audio.', 1
);

