INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-01', 'pronunciation', 10, 'Lesson 1 — Japanese vowel sounds',
  'Five Japanese vowels. Keep them short and clear; Japanese spelling is remarkably consistent once these sounds are familiar.',
  '{"id":"lesson-01","title":"Lesson 1 — Japanese vowel sounds","summary":"Five Japanese vowels. Keep them short and clear; Japanese spelling is remarkably consistent once these sounds are familiar.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"phonemes":[{"letter":"あ","name":"a","ipa":"/a/","englishApproximation":"Like the a in father.","description":"Open and short. Do not turn it into the English diphthong in day.","examples":[{"pl":"ありがとう","en":"thank you"}]},{"letter":"い","name":"i","ipa":"/i/","englishApproximation":"Like ee in see, but shorter.","description":"Keep the vowel clean and even.","examples":[{"pl":"いいえ","en":"no"}]},{"letter":"う","name":"u","ipa":"/ɯ/","englishApproximation":"A light, unrounded oo sound.","description":"The lips stay relaxed rather than rounded like English oo.","examples":[{"pl":"すし","en":"sushi"}]},{"letter":"え","name":"e","ipa":"/e/","englishApproximation":"Like e in bed, but tenser.","description":"A steady pure vowel, never the glide in English say.","examples":[{"pl":"えき","en":"station"}]},{"letter":"お","name":"o","ipa":"/o/","englishApproximation":"Like o in note, without a glide.","description":"A rounded but short pure vowel.","examples":[{"pl":"おはよう","en":"good morning"}]}]}'
);

INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-02', 'verbs', 20, 'Lesson 2 — Essential Japanese verbs',
  'Ten high-frequency dictionary verbs and their polite present forms. Japanese verbs do not change by grammatical person, so each row is deliberately the same across the pronoun grid.',
  '{"id":"lesson-02","title":"Lesson 2 — Essential Japanese verbs","summary":"Ten high-frequency dictionary verbs and their polite present forms. Japanese verbs do not change by grammatical person, so each row is deliberately the same across the pronoun grid.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"verbs":[{"lemma":"する","en":"to do","forms":{"1sg":"します","2sg":"します","3sg":"します","1pl":"します","2pl":"します","3pl":"します"}},{"lemma":"行く","en":"to go","forms":{"1sg":"行きます","2sg":"行きます","3sg":"行きます","1pl":"行きます","2pl":"行きます","3pl":"行きます"}},{"lemma":"来る","en":"to come","forms":{"1sg":"来ます","2sg":"来ます","3sg":"来ます","1pl":"来ます","2pl":"来ます","3pl":"来ます"}},{"lemma":"食べる","en":"to eat","forms":{"1sg":"食べます","2sg":"食べます","3sg":"食べます","1pl":"食べます","2pl":"食べます","3pl":"食べます"}},{"lemma":"飲む","en":"to drink","forms":{"1sg":"飲みます","2sg":"飲みます","3sg":"飲みます","1pl":"飲みます","2pl":"飲みます","3pl":"飲みます"}},{"lemma":"見る","en":"to see / watch","forms":{"1sg":"見ます","2sg":"見ます","3sg":"見ます","1pl":"見ます","2pl":"見ます","3pl":"見ます"}},{"lemma":"話す","en":"to speak","forms":{"1sg":"話します","2sg":"話します","3sg":"話します","1pl":"話します","2pl":"話します","3pl":"話します"}},{"lemma":"聞く","en":"to listen / ask","forms":{"1sg":"聞きます","2sg":"聞きます","3sg":"聞きます","1pl":"聞きます","2pl":"聞きます","3pl":"聞きます"}},{"lemma":"買う","en":"to buy","forms":{"1sg":"買います","2sg":"買います","3sg":"買います","1pl":"買います","2pl":"買います","3pl":"買います"}},{"lemma":"分かる","en":"to understand","forms":{"1sg":"分かります","2sg":"分かります","3sg":"分かります","1pl":"分かります","2pl":"分かります","3pl":"分かります"}}],"pronouns":[{"lemma":"私","en":"I","case_forms":{"nom":"私は","acc":"私を","dat":"私に"}},{"lemma":"あなた","en":"you","case_forms":{"nom":"あなたは","acc":"あなたを","dat":"あなたに"}},{"lemma":"彼","en":"he","case_forms":{"nom":"彼は","acc":"彼を","dat":"彼に"}},{"lemma":"彼女","en":"she","case_forms":{"nom":"彼女は","acc":"彼女を","dat":"彼女に"}},{"lemma":"私たち","en":"we","case_forms":{"nom":"私たちは","acc":"私たちを","dat":"私たちに"}},{"lemma":"彼ら","en":"they","case_forms":{"nom":"彼らは","acc":"彼らを","dat":"彼らに"}}],"phrases":[]}'
);

INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-03', 'adjectives', 30, 'Lesson 3 — Core Japanese adjectives',
  'Ten common Japanese adjectives. The existing gender and case grid is held constant because Japanese adjectives do not agree with gender or number like Polish adjectives do.',
  '{"id":"lesson-03","title":"Lesson 3 — Core Japanese adjectives","summary":"Ten common Japanese adjectives. The existing gender and case grid is held constant because Japanese adjectives do not agree with gender or number like Polish adjectives do.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"adjectives":[{"lemma":"大きい","en":"big","nom":{"m":"大きい","f":"大きい","n":"大きい","mp":"大きい","other":"大きい"},"acc":{"m":"大きい","f":"大きい","n":"大きい","mp":"大きい","other":"大きい"}},{"lemma":"小さい","en":"small","nom":{"m":"小さい","f":"小さい","n":"小さい","mp":"小さい","other":"小さい"},"acc":{"m":"小さい","f":"小さい","n":"小さい","mp":"小さい","other":"小さい"}},{"lemma":"いい","en":"good","nom":{"m":"いい","f":"いい","n":"いい","mp":"いい","other":"いい"},"acc":{"m":"いい","f":"いい","n":"いい","mp":"いい","other":"いい"}},{"lemma":"美しい","en":"beautiful","nom":{"m":"美しい","f":"美しい","n":"美しい","mp":"美しい","other":"美しい"},"acc":{"m":"美しい","f":"美しい","n":"美しい","mp":"美しい","other":"美しい"}},{"lemma":"面白い","en":"interesting / funny","nom":{"m":"面白い","f":"面白い","n":"面白い","mp":"面白い","other":"面白い"},"acc":{"m":"面白い","f":"面白い","n":"面白い","mp":"面白い","other":"面白い"}},{"lemma":"忙しい","en":"busy","nom":{"m":"忙しい","f":"忙しい","n":"忙しい","mp":"忙しい","other":"忙しい"},"acc":{"m":"忙しい","f":"忙しい","n":"忙しい","mp":"忙しい","other":"忙しい"}},{"lemma":"元気な","en":"healthy / energetic","nom":{"m":"元気な","f":"元気な","n":"元気な","mp":"元気な","other":"元気な"},"acc":{"m":"元気な","f":"元気な","n":"元気な","mp":"元気な","other":"元気な"}},{"lemma":"静か","en":"quiet","nom":{"m":"静か","f":"静か","n":"静か","mp":"静か","other":"静か"},"acc":{"m":"静か","f":"静か","n":"静か","mp":"静か","other":"静か"}},{"lemma":"暑い","en":"hot weather","nom":{"m":"暑い","f":"暑い","n":"暑い","mp":"暑い","other":"暑い"},"acc":{"m":"暑い","f":"暑い","n":"暑い","mp":"暑い","other":"暑い"}},{"lemma":"寒い","en":"cold weather","nom":{"m":"寒い","f":"寒い","n":"寒い","mp":"寒い","other":"寒い"},"acc":{"m":"寒い","f":"寒い","n":"寒い","mp":"寒い","other":"寒い"}}]}'
);

INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-04', 'adverbs', 40, 'Lesson 4 — Everyday Japanese adverbs',
  'Ten useful time, place, and manner words for beginning Japanese conversations.',
  '{"id":"lesson-04","title":"Lesson 4 — Everyday Japanese adverbs","summary":"Ten useful time, place, and manner words for beginning Japanese conversations.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"adverbs":[{"lemma":"とても","en":"very"},{"lemma":"少し","en":"a little"},{"lemma":"今","en":"now"},{"lemma":"今日","en":"today"},{"lemma":"明日","en":"tomorrow"},{"lemma":"ここ","en":"here"},{"lemma":"一緒に","en":"together"},{"lemma":"ゆっくり","en":"slowly"},{"lemma":"すぐに","en":"right away"},{"lemma":"いつも","en":"always"}]}'
);

INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-05', 'phrases', 50, 'Lesson 5 — Japanese essentials',
  'Twenty-five greetings, introductions, everyday phrases, and gentle jokes. The last group is friendly only when the situation is relaxed; delivery and timing matter.',
  '{"id":"lesson-05","title":"Lesson 5 — Japanese essentials","summary":"Twenty-five greetings, introductions, everyday phrases, and gentle jokes. The last group is friendly only when the situation is relaxed; delivery and timing matter.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"groups":[{"id":"greetings","title":"Greetings and salutations","subtitle":"Useful greetings for morning, day, evening, and polite exchanges.","sentences":[{"en":"Good morning.","pl":"おはようございます。","literal":"good morning"},{"en":"Hello / good afternoon.","pl":"こんにちは。","literal":"hello"},{"en":"Good evening.","pl":"こんばんは。","literal":"good evening"},{"en":"Good night.","pl":"おやすみなさい。","literal":"good night"},{"en":"Thank you very much.","pl":"ありがとうございます。","literal":"thank you"},{"en":"You are welcome.","pl":"どういたしまして。","literal":"it is nothing"},{"en":"Excuse me / I am sorry.","pl":"すみません。","literal":"excuse me"}]},{"id":"introductions","title":"Introductions and learning","subtitle":"Introduce yourself and keep a conversation moving while you learn.","sentences":[{"en":"Nice to meet you.","pl":"はじめまして。","literal":"first meeting"},{"en":"My name is Alex.","pl":"私はアレックスです。","literal":"I am Alex"},{"en":"What is your name?","pl":"お名前は何ですか。","literal":"your name is what"},{"en":"Please treat me kindly.","pl":"よろしくお願いします。","literal":"please favor me"},{"en":"I am studying Japanese.","pl":"日本語を勉強しています。","literal":"Japanese language am studying"},{"en":"I do not understand Japanese very well.","pl":"日本語があまり分かりません。","literal":"Japanese much do not understand"},{"en":"Could you say that once more, please?","pl":"もう一度言ってください。","literal":"one more time please say"}]},{"id":"out-and-about","title":"Out and about","subtitle":"A few high-value phrases for food, travel, and everyday conversation.","sentences":[{"en":"Can you speak English?","pl":"英語を話せますか。","literal":"English can speak"},{"en":"Where is the restroom?","pl":"トイレはどこですか。","literal":"restroom is where"},{"en":"How much is this?","pl":"これはいくらですか。","literal":"this is how much"},{"en":"This is delicious.","pl":"おいしいです。","literal":"is delicious"},{"en":"Do you have a recommendation?","pl":"おすすめはありますか。","literal":"recommendation is there"},{"en":"That was fun.","pl":"楽しかったです。","literal":"was enjoyable"},{"en":"It is nice weather, is it not?","pl":"いい天気ですね。","literal":"good weather right"}]},{"id":"lighthearted","title":"Lighthearted Japanese","subtitle":"Common, self-deprecating lines for a relaxed moment — use a smile and read the room.","sentences":[{"en":"My Japanese still has a long way to go.","pl":"日本語はまだまだです。","literal":"Japanese is still still"},{"en":"My diet starts tomorrow.","pl":"ダイエットは明日からです。","literal":"diet is from tomorrow"},{"en":"I am so busy I could borrow a cats paws.","pl":"猫の手も借りたいです。","literal":"even cats paws want to borrow"},{"en":"I am so hungry my stomach and back might stick together.","pl":"お腹と背中がくっつきそうです。","literal":"stomach and back seem likely to stick together"}]}]}'
);

INSERT OR REPLACE INTO content_lessons (content_version_id, lesson_id, lesson_type, sort_order, title, summary, payload_json)
VALUES (
  'en-ja-v1', 'lesson-06', 'nouns', 60, 'Lesson 6 — Core Japanese nouns',
  'Ten high-frequency Japanese nouns. Japanese does not require the Polish-style case and plural grid, so each map repeats the usable base form.',
  '{"id":"lesson-06","title":"Lesson 6 — Core Japanese nouns","summary":"Ten high-frequency Japanese nouns. Japanese does not require the Polish-style case and plural grid, so each map repeats the usable base form.","schema":"langbangml.en-ja.compat.v1","sourceLocale":"en-US","targetLocale":"ja-JP","sourceField":"en","targetField":"pl","fieldLocales":{"en":"en-US","pl":"ja-JP","source":"en-US","target":"ja-JP"},"nouns":[{"lemma":"人","en":"person","gender":"ja","nom":{"sg":"人","pl":"人"},"acc":{"sg":"人","pl":"人"},"gen":{"sg":"人","pl":"人"}},{"lemma":"友達","en":"friend","gender":"ja","nom":{"sg":"友達","pl":"友達"},"acc":{"sg":"友達","pl":"友達"},"gen":{"sg":"友達","pl":"友達"}},{"lemma":"水","en":"water","gender":"ja","nom":{"sg":"水","pl":"水"},"acc":{"sg":"水","pl":"水"},"gen":{"sg":"水","pl":"水"}},{"lemma":"食べ物","en":"food","gender":"ja","nom":{"sg":"食べ物","pl":"食べ物"},"acc":{"sg":"食べ物","pl":"食べ物"},"gen":{"sg":"食べ物","pl":"食べ物"}},{"lemma":"家","en":"house / home","gender":"ja","nom":{"sg":"家","pl":"家"},"acc":{"sg":"家","pl":"家"},"gen":{"sg":"家","pl":"家"}},{"lemma":"駅","en":"station","gender":"ja","nom":{"sg":"駅","pl":"駅"},"acc":{"sg":"駅","pl":"駅"},"gen":{"sg":"駅","pl":"駅"}},{"lemma":"本","en":"book","gender":"ja","nom":{"sg":"本","pl":"本"},"acc":{"sg":"本","pl":"本"},"gen":{"sg":"本","pl":"本"}},{"lemma":"お茶","en":"tea","gender":"ja","nom":{"sg":"お茶","pl":"お茶"},"acc":{"sg":"お茶","pl":"お茶"},"gen":{"sg":"お茶","pl":"お茶"}},{"lemma":"猫","en":"cat","gender":"ja","nom":{"sg":"猫","pl":"猫"},"acc":{"sg":"猫","pl":"猫"},"gen":{"sg":"猫","pl":"猫"}},{"lemma":"日本","en":"Japan","gender":"ja","nom":{"sg":"日本","pl":"日本"},"acc":{"sg":"日本","pl":"日本"},"gen":{"sg":"日本","pl":"日本"}}]}'
);
